import React from 'react';
import { Chart as ChartJS, ArcElement, Tooltip, Legend } from 'chart.js';
import { Doughnut } from 'react-chartjs-2';
import { ShieldCheck, AlertTriangle, ChevronRight } from 'lucide-react';

ChartJS.register(ArcElement, Tooltip, Legend);

const CriticalityChart = ({ high = 0, medium = 0, low = 0 }) => {
  const total = high + medium + low || 1;
  const highPct = Math.round((high / total) * 100);
  const mediumPct = Math.round((medium / total) * 100);
  const lowPct = Math.round((low / total) * 100);

  const data = {
    labels: [`High (${highPct}%)`, `Medium (${mediumPct}%)`, `Low (${lowPct}%)`],
    datasets: [
      {
        data: [high, medium, low],
        backgroundColor: ['#7C3AED', '#D97706', '#4F46E5'],
        borderColor: ['#ffffff', '#ffffff', '#ffffff'],
        borderWidth: 2,
        hoverOffset: 4,
      },
    ],
  };

  const options = {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: {
        position: 'bottom',
        labels: {
          color: '#0F172A',
          font: { family: 'Plus Jakarta Sans', size: 12, weight: '800' },
          usePointStyle: true,
          boxWidth: 8,
          padding: 10,
        },
      },
      tooltip: {
        backgroundColor: '#0F172A',
        titleColor: '#FFFFFF',
        bodyColor: '#E2E8F0',
        borderColor: '#E2E8F0',
        borderWidth: 1,
      },
    },
    cutout: '72%',
  };

  // High risk watchlist items
  const watchlist = [
    { machineId: 'LOOM-201', name: 'Dornier Heavy Shuttleless', health: 68, reason: 'Bearing fatigue' },
    { machineId: 'LOOM-104', name: 'Tsudakoma Water Jet', health: 88, reason: 'Nozzle scale build-up' },
  ];

  return (
    <div className="glass-card" style={{ padding: '1.5rem', display: 'flex', flexDirection: 'column', height: '100%' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '0.75rem' }}>
        <h3 style={{ fontSize: '1.05rem', fontWeight: '800', color: '#0F172A', display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
          <ShieldCheck size={18} style={{ color: 'var(--status-critical)' }} /> Criticality Distribution
        </h3>
        <span style={{ fontSize: '0.78rem', color: '#7C3AED', fontWeight: '800' }}>AI Risk Index</span>
      </div>

      {/* Donut Chart Canvas */}
      <div style={{ height: '210px', width: '100%', position: 'relative' }}>
        <Doughnut data={data} options={options} />
        {/* Center Donut Metric Counter */}
        <div
          style={{
            position: 'absolute',
            top: '36%',
            left: '50%',
            transform: 'translate(-50%, -50%)',
            textAlign: 'center',
            pointerEvents: 'none',
          }}
        >
          <div style={{ fontSize: '2rem', fontWeight: '800', color: '#7C3AED', lineHeight: 1 }}>{high}</div>
          <div style={{ fontSize: '0.72rem', fontWeight: '800', color: '#334155', marginTop: '3px', letterSpacing: '0.5px' }}>
            HIGH RISK
          </div>
        </div>
      </div>

      {/* Filled Free Space Widget: High-Risk Critical Watchlist */}
      <div
        style={{
          background: 'var(--status-critical-bg)',
          border: '1px solid rgba(124, 58, 237, 0.25)',
          borderRadius: 'var(--radius-sm)',
          padding: '0.75rem 0.85rem',
          marginTop: '0.5rem',
          display: 'flex',
          flexDirection: 'column',
          gap: '0.4rem',
        }}
      >
        <div style={{ fontSize: '0.78rem', fontWeight: '800', color: '#7C3AED', display: 'flex', alignItems: 'center', gap: '0.35rem' }}>
          <AlertTriangle size={14} /> HIGH-RISK WATCHLIST
        </div>

        {watchlist.map((item) => (
          <div key={item.machineId} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', fontSize: '0.8rem', fontWeight: '800', color: '#0F172A', background: 'rgba(255, 255, 255, 0.8)', padding: '0.35rem 0.6rem', borderRadius: '4px' }}>
            <div>
              <span style={{ color: 'var(--accent-primary)', fontFamily: 'JetBrains Mono', marginRight: '6px' }}>{item.machineId}</span>
              <span>{item.name}</span>
            </div>
            <span style={{ color: item.health < 80 ? 'var(--status-maintenance)' : 'var(--status-idle)', fontWeight: '800' }}>
              {item.health}%
            </span>
          </div>
        ))}
      </div>
    </div>
  );
};

export default CriticalityChart;
